sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
   if (isLoading || newValue === '') {
      return;
   }

   var value = g_form.getValue('how_many_rooms_are_en_suite');

    if (isNaN(value) || value === '' || value === null) {
        g_form.showFieldMsg('how_many_rooms_are_en_suite', 'Please enter a valid numeric value.', 'error');
        // g_form.setValue('deposit_amount', '');
    } else if (parseFloat(value) < 0) {
        g_form.showFieldMsg('how_many_rooms_are_en_suite', 'Value cannot be less than zero.', 'error');
        // g_form.setValue('deposit_amount', '');
    }

}
